  `question_type` VARCHAR(255) DEFAULT 'mcq',
  `difficulty_level` VARCHAR(255) DEFAULT 'medium',
  `explanation` LONGTEXT,
  `tamil_text` TEXT,
  `tamil_explanation` TEXT,
  `is_pyq` INT DEFAULT 0,
  `pyq_year` INT,
  `pyq_source` TEXT,
  `created_by` VARCHAR(255) DEFAULT 'system',
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Data for `questions` (21 rows)
INSERT INTO `questions` (`id`, `topic_id`, `exam_id`, `question_text`, `question_type`, `difficulty_level`, `explanation`, `tamil_text`, `tamil_explanation`, `is_pyq`, `pyq_year`, `pyq_source`, `created_by`, `created_at`) VALUES ('q_upsc_pol_01', 'top_fr_dpsp', 'exam_upsc_cse', 'Which one of the following statements regarding the Writ of Mandamus in India is correct?', 'mcq', 'medium', 'Mandamus cannot be granted against the President of India or the Governor of a State for the exercise and performance of the powers and duties of his office (Article 361). It also does not lie against a private individual or private body without public statutory duties.', 'இந்தியாவில் செயலுறுத்தும் நீதிப்பேராணை (Mandamus) பற்றிய பின்வரும் கூற்றுகளில் எது சரியானது?', 'இந்தியக் குடியரசுத் தலைவர் அல்லது மாநில ஆளுநருக்கு எதிராக அவர்களின் அதிகாரங்கள் மற்றும் கடமைகளைச் செயல்படுத்துவதற்காக மாண்டமஸ் ஆணை பிறப்பிக்க முடியாது (சரத்து 361).', 1, 2022, 'UPSC CSE Prelims GS-I (Question 34)', 'system', '2026-08-27 09:11:41');
INSERT INTO `questions` (`id`, `topic_id`, `exam_id`, `question_text`, `question_type`, `difficulty_level`, `explanation`, `tamil_text`, `tamil_explanation`, `is_pyq`, `pyq_year`, `pyq_source`, `created_by`, `created_at`) VALUES ('q_upsc_pol_02', 'top_fr_dpsp', 'exam_upsc_cse', 'A legislation which confers on the executive or administrative authority an unguided and uncontrolled discretionary power in the matter of application of law violates which one of the following Articles of the Constitution of India?', 'mcq', 'hard', 'Arbitrary and unguided executive discretion violates Article 14 (Right to Equality and Non-Arbitrariness as established in the EP Royappa and Maneka Gandhi cases).', 'சட்டத்தைப் பயன்படுத்துவதில் நிர்வாக அதிகாரத்திற்கு வழிகாட்டப்படாத மற்றும் கட்டுப்பாடற்ற விருப்புரிமை அதிகாரத்தை வழங்கும் சட்டம், இந்திய அரசியலமைப்பின் பின்வரும் எந்த சரத்தை மீறுகிறது?', 'வழிகாட்டப்படாத தன்னிச்சையான நிர்வாக அதிகாரம் சரத்து 14-ஐ (சமத்துவ உரிமை மற்றும் தன்னிச்சையின்மை) மீறுகிறது.', 1, 2021, 'UPSC CSE Prelims GS-I (Question 18)', 'system', '2026-08-27 09:11:41');
INSERT INTO `questions` (`id`, `topic_id`, `exam_id`, `question_text`, `question_type`, `difficulty_level`, `explanation`, `tamil_text`, `tamil_explanation`, `is_pyq`, `pyq_year`, `pyq_source`, `created_by`, `created_at`) VALUES ('q_upsc_pol_03', 'top_parliament', 'exam_upsc_cse', 'With reference to the Union Parliament in India, consider the following statements:\n1. The Speaker of the Lok Sabha decides whether a Bill is a Money Bill or not, and this endorsement is final.\n2. The Speaker can vote in the first instance in all legislative ballots.', 'mcq', 'medium', 'Statement 1 is correct under Article 110(3). Statement 2 is incorrect because the Speaker does not vote in the first instance; they only exercise a casting vote in the event of an equality of votes (Article 100(1)).', 'இந்திய நாடாளுமன்றம் தொடர்பாக பின்வரும் கூற்றுகளைக் கவனியுங்கள்:\n1. ஒரு மசோதா பண மசோதாவா இல்லையா என்பதை மக்களவை சபாநாயகர் தீர்மானிக்கிறார், அவரின் முடிவு இறுதியானது.\n2. சபாநாயகர் அனைத்து மசோதாக்களிலும் முதல் நிலையிலேயே வாக்களிக்கலாம்.', 'கூற்று 1 சரி. கூற்று 2 தவறு, ஏனெனில் சபாநாயகர் சமநிலை ஏற்படும் போது மட்டுமே முடிவு வாக்கு (casting vote) அளிக்க முடியும்.', 1, 2023, 'UPSC CSE Prelims GS-I (Question 52)', 'system', '2026-08-27 09:11:41');
INSERT INTO `questions` (`id`, `topic_id`, `exam_id`, `question_text`, `question_type`, `difficulty_level`, `explanation`, `tamil_text`, `tamil_explanation`, `is_pyq`, `pyq_year`, `pyq_source`, `created_by`, `created_at`) VALUES ('q_upsc_pol_04', 'top_judiciary', 'exam_upsc_cse', 'Which of the following statements is correct regarding the "Doctrine of Basic Structure" of the Indian Constitution?', 'mcq', 'medium', 'The Doctrine was propounded in Kesavananda Bharati v. State of Kerala (1973). The Constitution itself does not define the Basic Structure; it is an organic doctrine defined by the Judiciary on a case-by-case basis.', 'இந்திய அரசியலமைப்பின் "அடிப்படை கட்டமைப்பு கோட்பாடு" (Basic Structure) பற்றிய பின்வரும் கூற்றுகளில் எது சரியானது?', 'இக்கோட்பாடு 1973 கேசவானந்த பாரதி வழக்கில் உச்ச நீதிமன்றத்தால் உருவாக்கப்பட்டது. அரசியலமைப்பு இதை வெளிப்படையாக வரையறுக்கவில்லை.', 1, 2020, 'UPSC CSE Prelims GS-I', 'system', '2026-08-27 09:11:41');
INSERT INTO `questions` (`id`, `topic_id`, `exam_id`, `question_text`, `question_type`, `difficulty_level`, `explanation`, `tamil_text`, `tamil_explanation`, `is_pyq`, `pyq_year`, `pyq_source`, `created_by`, `created_at`) VALUES ('q_upsc_pol_05', 'top_fed_emergency', 'exam_upsc_cse', 'Under Article 356 of the Constitution of India, if the President of India imposes President\'s Rule on a State, which of the following is NOT an automatic consequence?', 'mcq', 'hard', 'Under Article 356, the State Council of Ministers is dismissed automatically, but the State Legislative Assembly is either kept in suspended animation or dissolved. Dissolution of the Assembly is NOT automatic until Parliament approves the proclamation (S.R. Bommai case).', 'சரத்து 356-ன் கீழ் ஒரு மாநிலத்தில் குடியரசுத் தலைவர் ஆட்சி அமல்படுத்தப்பட்டால், பின்வருவனவற்றில் எது தானாகவே நிகழும் விளைவு அல்ல?', 'சட்டப்பேரவை தானாகவே கலைக்கப்படாது; நாடாளுமன்ற ஒப்புதலுக்குப் பிறகே கலைக்கப்பட முடியும் (பொம்மை வழக்கு தீர்ப்பு).', 1, 2023, 'UPSC CSE Prelims GS-I', 'system', '2026-08-27 09:11:41');
INSERT INTO `questions` (`id`, `topic_id`, `exam_id`, `question_text`, `question_type`, `difficulty_level`, `explanation`, `tamil_text`, `tamil_explanation`, `is_pyq`, `pyq_year`, `pyq_source`, `created_by`, `created_at`) VALUES ('q_upsc_eco_01', 'top_monetary_rbi', 'exam_upsc_cse', 'If the RBI decides to adopt an expansionary monetary policy, which of the following will it NOT do?\n1. Cut and optimize the Statutory Liquidity Ratio (SLR)\n2. Increase the Marginal Standing Facility (MSF) rate\n3. Cut the Bank Rate and Repo Rate', 'mcq', 'hard', 'Under expansionary monetary policy, RBI wants to inject liquidity and reduce borrowing costs. Increasing the MSF rate tightens liquidity and raises interest rates (contractionary), so RBI will NOT do statement 2.', 'ரிசர்வ் வங்கி ஒரு விரிவாக்க நாணயக் கொள்கையைக் கடைப்பிடிக்க முடிவு செய்தால், அது பின்வருவனவற்றில் எதைச் செய்யாது?', 'விரிவாக்க நாணயக் கொள்கையில் MSF விகிதத்தை அதிகரிப்பது பணப்புழக்கத்தைக் குறைக்கும், எனவே அதைச் செய்யாது (2 மட்டும்).', 1, 2020, 'UPSC CSE Prelims GS-I (Question 41)', 'system', '2026-08-27 09:11:41');
INSERT INTO `questions` (`id`, `topic_id`, `exam_id`, `question_text`, `question_type`, `difficulty_level`, `explanation`, `tamil_text`, `tamil_explanation`, `is_pyq`, `pyq_year`, `pyq_source`, `created_by`, `created_at`) VALUES ('q_upsc_eco_02', 'top_monetary_rbi', 'exam_upsc_cse', 'Which of the following is the primary operational distinction of the Standing Deposit Facility (SDF) introduced by the RBI?', 'mcq', 'medium', 'SDF allows RBI to absorb excess liquidity from commercial banks without providing collateral (government securities), unlike reverse repo operations.', 'ரிசர்வ் வங்கியால் அறிமுகப்படுத்தப்பட்ட SDF (Standing Deposit Facility) முறையின் முதன்மை அம்சம் என்ன?', 'SDF முறையில் அரசுப் பத்திரங்களை பிணையமாக வழங்காமல் ரிசர்வ் வங்கி வணிக வங்கிகளிடமிருந்து உபரி பணத்தை உறிஞ்சுகிறது.', 1, 2023, 'UPSC CSE Prelims GS-I', 'system', '2026-08-27 09:11:41');
INSERT INTO `questions` (`id`, `topic_id`, `exam_id`, `question_text`, `question_type`, `difficulty_level`, `explanation`, `tamil_text`, `tamil_explanation`, `is_pyq`, `pyq_year`, `pyq_source`, `created_by`, `created_at`) VALUES ('q_upsc_eco_03', 'top_fiscal_budget', 'exam_upsc_cse', 'In the context of Indian public finance, what does "Primary Deficit" signify?', 'mcq', 'easy', 'Primary Deficit = Fiscal Deficit - Interest Payments. It measures government borrowing requirements excluding the liability of servicing past debt.', 'இந்தியப் பொது நிதியில், "முதன்மைப் பற்றாக்குறை" (Primary Deficit) எதைக் குறிக்கிறது?', 'முதன்மைப் பற்றாக்குறை = நிதிப் பற்றாக்குறை - வட்டி செலுத்துதல்கள்.', 1, 2021, 'UPSC CSE Prelims GS-I', 'system', '2026-08-27 09:11:41');
INSERT INTO `questions` (`id`, `topic_id`, `exam_id`, `question_text`, `question_type`, `difficulty_level`, `explanation`, `tamil_text`, `tamil_explanation`, `is_pyq`, `pyq_year`, `pyq_source`, `created_by`, `created_at`) VALUES ('q_tnpsc_u8_01', 'top_tn_thirukkural', 'exam_tnpsc_grp2', 'According to Thirukkural Chapter 39 (Irai Matchi), what are the four essential attributes of a righteous state/government?\n"இயற்றலும் ஈட்டலும் காத்தலும் காத்த..."', 'mcq', 'medium', 'Kural 385 states: An able ruler creates revenue sources (Iyattral), accumulates wealth efficiently (Eettal), protects the treasury (Kaathal), and allocates wealth justly for public welfare (Vaguthal).', 'திருக்குறளின் 39-வது அதிகாரம் (இறைமாட்சி) படி, ஒரு சிறந்த அரசின் நான்கு முக்கிய பணிகள் யாவை?', 'பொருள் வரும் வழிகளை உருவாக்குதல் (இயற்றல்), பொருளைச் சேர்த்தல் (ஈட்டல்), சேர்த்த பொருளைப் பாதுகாத்தல் (காத்தல்), காத்த பொருளை பயனுள்ள வழிகளில் வகுத்துச் செலவிடுதல் (வகுத்தல்).', 1, 2022, 'TNPSC Group 2 Prelims (General Studies)', 'system', '2026-08-27 09:11:41');
INSERT INTO `questions` (`id`, `topic_id`, `exam_id`, `question_text`, `question_type`, `difficulty_level`, `explanation`, `tamil_text`, `tamil_explanation`, `is_pyq`, `pyq_year`, `pyq_source`, `created_by`, `created_at`) VALUES ('q_tnpsc_u8_02', 'top_tn_dravidian_move', 'exam_tnpsc_grp2', 'In which year was the historic First Communal Government Order (G.O. No. 613) issued by the Justice Party ministry in the Madras Presidency?', 'mcq', 'easy', 'The Justice Party passed the first Communal G.O. on 16 September 1921 providing formal communal representation in government jobs for non-Brahmins, Muslims, Indian Christians, and Adi-Dravidars.', 'மெட்ராஸ் மாகாணத்தில் நீதிக்கட்சி அமைச்சரவையால் வரலாற்றுச் சிறப்புமிக்க முதல் வகுப்புவாரி அரசாணை (Communal G.O.) எந்த ஆண்டு பிறப்பிக்கப்பட்டது?', 'நீதிக்கட்சி செப்டம்பர் 16, 1921 அன்று முதல் வகுப்புவாரி அரசாணையை (G.O. No. 613) பிறப்பித்தது.', 1, 2022, 'TNPSC Group 1 / Group 2 Prelims', 'system', '2026-08-27 09:11:41');
INSERT INTO `questions` (`id`, `topic_id`, `exam_id`, `question_text`, `question_type`, `difficulty_level`, `explanation`, `tamil_text`, `tamil_explanation`, `is_pyq`, `pyq_year`, `pyq_source`, `created_by`, `created_at`) VALUES ('q_tnpsc_u8_03', 'top_tn_freedom_struggle', 'exam_tnpsc_grp2', 'Who founded the "Swadeshi Steam Navigation Company" in 1906 to challenge the British India Steam Navigation Company monopoly?', 'mcq', 'easy', 'V.O. Chidambaram Pillai (Kappalottiya Thamizhan) launched the Swadeshi Steam Navigation Company between Tuticorin and Colombo in 1906.', 'பிரிட்டிஷ் கப்பல் நிறுவனத்தின் ஏகபோகத்திற்கு எதிராக 1906-ல் "சுதேசி நீராவி கப்பல் கம்பெனியை" நிறுவியவர் யார்?', 'வ.உ. சிதம்பரனார் (கப்பலோட்டிய தமிழன்) தூத்துக்குடிக்கும் கொழும்புக்கும் இடையே சுதேசி கப்பலை இயக்கினார்.', 1, 2023, 'TNPSC Group 2 Prelims', 'system', '2026-08-27 09:11:41');
INSERT INTO `questions` (`id`, `topic_id`, `exam_id`, `question_text`, `question_type`, `difficulty_level`, `explanation`, `tamil_text`, `tamil_explanation`, `is_pyq`, `pyq_year`, `pyq_source`, `created_by`, `created_at`) VALUES ('q_tnpsc_u9_01', 'top_tn_hdi_welfare', 'exam_tnpsc_grp2', 'Under the 76th Constitutional Amendment Act of 1994, the Tamil Nadu Backward Classes and Scheduled Castes Reservation Act providing 69% reservation was placed under which Schedule of the Indian Constitution?', 'mcq', 'medium', 'The 76th Amendment Act of 1994 placed the Tamil Nadu Act of 1994 in the 9th Schedule to protect it from judicial review under Article 31B.', '1994-ஆம் ஆண்டின் 76-வது அரசியலமைப்புத் திருத்தச் சட்டத்தின்படி, தமிழ்நாட்டின் 69% இடஒதுக்கீட்டுச் சட்டம் இந்திய அரசியலமைப்பின் எந்த அட்டவணையில் சேர்க்கப்பட்டது?', 'தமிழ்நாட்டின் 69% இடஒதுக்கீட்டுச் சட்டம் 9-வது அட்டவணையில் சேர்க்கப்பட்டது.', 1, 2021, 'TNPSC Group 1 Prelims', 'system', '2026-08-27 09:11:41');
INSERT INTO `questions` (`id`, `topic_id`, `exam_id`, `question_text`, `question_type`, `difficulty_level`, `explanation`, `tamil_text`, `tamil_explanation`, `is_pyq`, `pyq_year`, `pyq_source`, `created_by`, `created_at`) VALUES ('q_tnpsc_apt_01', 'top_tnpsc_ratio_perc', 'exam_tnpsc_grp2', 'If the difference between Compound Interest and Simple Interest on a certain sum of money for 2 years at 8% per annum is ₹64, find the principal sum.', 'mcq', 'medium', 'Difference formula for 2 years: D = P * (R/100)^2. => 64 = P * (8/100)^2 => 64 = P * (64/10000) => P = ₹10,000.', 'ஒரு குறிப்பிட்ட அசலுக்கு 8% ஆண்டு வட்டியில் 2 ஆண்டுகளுக்கு கிடைக்கும் கூட்டு வட்டி மற்றும் தனி வட்டிக்கு இடையேயான வித்தியாசம் ₹64 எனில் அசல் தொகையைக் காண்க.', '2 ஆண்டுகளுக்கான வித்தியாசம்: D = P * (R/100)^2 => 64 = P * (64/10000) => அசல் P = ₹10,000.', 1, 2023, 'TNPSC Group 2 Aptitude', 'system', '2026-08-27 09:11:41');
INSERT INTO `questions` (`id`, `topic_id`, `exam_id`, `question_text`, `question_type`, `difficulty_level`, `explanation`, `tamil_text`, `tamil_explanation`, `is_pyq`, `pyq_year`, `pyq_source`, `created_by`, `created_at`) VALUES ('q_ssc_quant_01', 'top_ssc_percentage_profit', 'exam_ssc_cgl', 'A dishonest dealer professes to sell his goods at cost price, but uses a false weight of 900 grams instead of a 1 kg weight. What is his net gain percentage?', 'mcq', 'medium', 'Gain % = (Error / (True Value - Error)) * 100 = (100 / 900) * 100 = 100/9 = 11 1/9% (or 11.11%).', '', '', 1, 2023, 'SSC CGL Tier-I (Shift 2)', 'system', '2026-08-27 09:11:41');
INSERT INTO `questions` (`id`, `topic_id`, `exam_id`, `question_text`, `question_type`, `difficulty_level`, `explanation`, `tamil_text`, `tamil_explanation`, `is_pyq`, `pyq_year`, `pyq_source`, `created_by`, `created_at`) VALUES ('q_ssc_quant_02', 'top_ssc_algebra_geom', 'exam_ssc_cgl', 'In a triangle ABC, the bisector of angle A meets BC at D. If AB = 8 cm, AC = 12 cm, and BC = 10 cm, what is the length of BD?', 'mcq', 'medium', 'By Angle Bisector Theorem: BD / DC = AB / AC = 8 / 12 = 2 / 3. Since BC = 10 cm, BD = (2 / (2+3)) * 10 = (2/5) * 10 = 4 cm.', '', '', 1, 2022, 'SSC CGL Tier-I', 'system', '2026-08-27 09:11:41');
INSERT INTO `questions` (`id`, `topic_id`, `exam_id`, `question_text`, `question_type`, `difficulty_level`, `explanation`, `tamil_text`, `tamil_explanation`, `is_pyq`, `pyq_year`, `pyq_source`, `created_by`, `created_at`) VALUES ('q_ssc_reas_01', 'top_ssc_syllogism', 'exam_ssc_cgl', 'Statements:\n1. All Rivers are Water.\n2. Some Water are Lakes.\n3. No Lake is an Ocean.\nConclusions:\nI. Some Water are not Oceans.\nII. Some Rivers being Oceans is a possibility.', 'mcq', 'hard', 'Conclusion I is correct because the portion of Water that is Lakes cannot be Oceans. Conclusion II is also correct because there is no direct negative relation between Rivers and Oceans. Hence, Both I and II follow.', '', '', 1, 2023, 'SSC CGL Tier-I', 'system', '2026-08-27 09:11:41');
INSERT INTO `questions` (`id`, `topic_id`, `exam_id`, `question_text`, `question_type`, `difficulty_level`, `explanation`, `tamil_text`, `tamil_explanation`, `is_pyq`, `pyq_year`, `pyq_source`, `created_by`, `created_at`) VALUES ('q_ssc_eng_01', 'top_ssc_grammar_error', 'exam_ssc_cgl', 'Identify the segment in the sentence which contains a grammatical error:\n"Scarcely had he gone a few steps (A) / than he was struck by (B) / a sudden flash of lightning (C) / and fell down (D)."', 'mcq', 'medium', 'Correlative conjunction rule: "Scarcely... when" is used, not "Scarcely... than". "Than" is used with "No sooner". Part (B) contains the error.', '', '', 1, 2022, 'SSC CGL Tier-I English', 'system', '2026-08-27 09:11:41');
INSERT INTO `questions` (`id`, `topic_id`, `exam_id`, `question_text`, `question_type`, `difficulty_level`, `explanation`, `tamil_text`, `tamil_explanation`, `is_pyq`, `pyq_year`, `pyq_source`, `created_by`, `created_at`) VALUES ('q_bank_quant_01', 'top_bank_di', 'exam_bank_po', 'Directions: In the quadratic equation I: 2x² - 13x + 20 = 0 and II: 2y² - 17y + 36 = 0, establish the relation between x and y.', 'mcq', 'medium', 'Equation I: 2x² - 8x - 5x + 20 = 0 => (2x - 5)(x - 4) = 0 => x = 2.5, 4.\nEquation II: 2y² - 8y - 9y + 36 = 0 => (2y - 9)(y - 4) = 0 => y = 4.5, 4.\nComparing roots: x = 2.5 < 4, 4.5; x = 4 < 4.5, x = 4 = 4. Thus x <= y.', '', '', 1, 2023, 'IBPS PO Prelims', 'system', '2026-08-27 09:11:41');
INSERT INTO `questions` (`id`, `topic_id`, `exam_id`, `question_text`, `question_type`, `difficulty_level`, `explanation`, `tamil_text`, `tamil_explanation`, `is_pyq`, `pyq_year`, `pyq_source`, `created_by`, `created_at`) VALUES ('q_bank_reas_01', 'top_bank_puzzles', 'exam_bank_po', 'Eight persons A, B, C, D, E, F, G, and H sit in a row facing North. A sits third to the left of D. Only two persons sit between D and G. H sits second to the right of G. If B sits immediately next to H, who sits at the extreme left end?', 'mcq', 'hard', 'Arrangement from left to right: A, C, E, D, F, G, B, H. The person at the extreme left end is A.', '', '', 1, 2022, 'SBI PO Prelims', 'system', '2026-08-27 09:11:41');
INSERT INTO `questions` (`id`, `topic_id`, `exam_id`, `question_text`, `question_type`, `difficulty_level`, `explanation`, `tamil_text`, `tamil_explanation`, `is_pyq`, `pyq_year`, `pyq_source`, `created_by`, `created_at`) VALUES ('q_rrb_sci_01', 'top_rrb_gen_science', 'exam_rrb_ntpc', 'What is the electrical resistance of a conductor inversely proportional to?', 'mcq', 'easy', 'Resistance R = ρ * (L / A). Resistance is directly proportional to length (L) and inversely proportional to the area of cross-section (A).', '', '', 1, 2021, 'RRB NTPC Stage-1 (CBT-1)', 'system', '2026-08-27 09:11:41');
INSERT INTO `questions` (`id`, `topic_id`, `exam_id`, `question_text`, `question_type`, `difficulty_level`, `explanation`, `tamil_text`, `tamil_explanation`, `is_pyq`, `pyq_year`, `pyq_source`, `created_by`, `created_at`) VALUES ('q_rrb_math_01', 'top_rrb_time_work', 'exam_rrb_ntpc', 'A can complete a piece of work in 12 days and B can complete it in 18 days. If they work together for 4 days, what fraction of work is left?', 'mcq', 'easy', 'LCM of 12 and 18 = 36 units total work. Efficiency of A = 3 units/day, B = 2 units/day. Combined = 5 units/day. In 4 days work done = 20 units. Work left = 36 - 20 = 16 units. Fraction left = 16 / 36 = 4 / 9.', '', '', 1, 2021, 'RRB NTPC CBT-1', 'system', '2026-08-27 09:11:41');

DROP TABLE IF EXISTS `question_options`;
CREATE TABLE `question_options` (
  `id` VARCHAR(64) PRIMARY KEY,
  `question_id` VARCHAR(64),
  `option_key` TEXT,
  `option_text` TEXT,
  `tamil_option_text` TEXT,
  `is_correct` INT DEFAULT 0
