DROP TABLE IF EXISTS `test_attempts`;
CREATE TABLE `test_attempts` (
  `id` VARCHAR(64) PRIMARY KEY,
  `user_id` VARCHAR(64),
  `test_id` VARCHAR(64),
  `score` DECIMAL(5,2) DEFAULT 0.0,
  `total_marks` DECIMAL(5,2) DEFAULT 0.0,
  `percentage` DECIMAL(5,2) DEFAULT 0.0,
  `total_questions` INT DEFAULT 0,
  `attempted_count` INT DEFAULT 0,
  `correct_count` INT DEFAULT 0,
  `incorrect_count` INT DEFAULT 0,
  `unanswered_count` INT DEFAULT 0,
  `accuracy` DECIMAL(5,2) DEFAULT 0.0,
  `time_taken_seconds` INT DEFAULT 0,
  `completed_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `test_answers`;
CREATE TABLE `test_answers` (
  `id` VARCHAR(64) PRIMARY KEY,
  `attempt_id` VARCHAR(64),
  `question_id` VARCHAR(64),
  `selected_option_key` TEXT,
  `is_correct` INT DEFAULT 0,
  `time_spent_seconds` DECIMAL(5,2) DEFAULT 0,
  `mistake_tag` TEXT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `performance_analytics`;
CREATE TABLE `performance_analytics` (
  `id` VARCHAR(64) PRIMARY KEY,
  `user_id` VARCHAR(64),
  `subject_id` VARCHAR(64),
  `tests_taken` INT DEFAULT 0,
  `total_questions_attempted` INT DEFAULT 0,
  `total_correct` INT DEFAULT 0,
  `average_accuracy` DECIMAL(5,2) DEFAULT 0.0,
  `average_speed_seconds` DECIMAL(5,2) DEFAULT 0.0,
  `mastery_level` VARCHAR(255) DEFAULT 'developing',
  `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `user_mistakes`;
CREATE TABLE `user_mistakes` (
  `id` VARCHAR(64) PRIMARY KEY,
  `user_id` VARCHAR(64),
  `topic_id` VARCHAR(64),
  `question_id` VARCHAR(64),
  `mistake_type` TEXT,
  `notes` LONGTEXT,
  `frequency_count` INT DEFAULT 1,
  `last_occurred_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  `status` VARCHAR(100) DEFAULT 'active'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `study_plans`;
CREATE TABLE `study_plans` (
  `id` VARCHAR(64) PRIMARY KEY,
  `user_id` VARCHAR(64),
  `plan_date` DATE,
  `status` VARCHAR(100) DEFAULT 'active',
  `total_planned_minutes` INT DEFAULT 120,
  `total_completed_minutes` INT DEFAULT 0,
  `generated_by` VARCHAR(255) DEFAULT 'ai_study_planner',
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

