DROP TABLE IF EXISTS `study_tasks`;
CREATE TABLE `study_tasks` (
  `id` VARCHAR(64) PRIMARY KEY,
  `plan_id` VARCHAR(64),
  `topic_id` VARCHAR(64),
  `task_type` TEXT,
  `title` VARCHAR(255),
  `description` TEXT,
  `planned_duration_minutes` INT DEFAULT 30,
  `completed_duration_minutes` INT DEFAULT 0,
  `is_completed` INT DEFAULT 0,
  `priority` VARCHAR(255) DEFAULT 'high',
  `due_time_slot` VARCHAR(255) DEFAULT 'morning',
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `revision_schedules`;
CREATE TABLE `revision_schedules` (
  `id` VARCHAR(64) PRIMARY KEY,
  `user_id` VARCHAR(64),
  `topic_id` VARCHAR(64),
  `revision_interval_stage` INT DEFAULT 1,
  `scheduled_date` DATE,
  `status` VARCHAR(100) DEFAULT 'pending',
  `priority` VARCHAR(255) DEFAULT 'normal',
  `reason` VARCHAR(255) DEFAULT 'spaced_repetition',
  `completed_at` TIMESTAMP NULL DEFAULT NULL,
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `current_affairs`;
CREATE TABLE `current_affairs` (
  `id` VARCHAR(64) PRIMARY KEY,
  `title` VARCHAR(255),
  `summary` TEXT,
  `detailed_analysis` TEXT,
  `category` VARCHAR(100),
  `source_name` TEXT,
  `source_url` VARCHAR(512),
  `is_verified` INT DEFAULT 1,
  `verification_notes` TEXT,
  `exam_relevance_tags` TEXT,
  `published_date` DATE,
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Data for `current_affairs` (4 rows)
INSERT INTO `current_affairs` (`id`, `title`, `summary`, `detailed_analysis`, `category`, `source_name`, `source_url`, `is_verified`, `verification_notes`, `exam_relevance_tags`, `published_date`, `created_at`) VALUES ('ca_01_rbi_mpc', 'RBI Monetary Policy Committee Maintains Repo Rate at 6.50% with Stance on Inflation Alignment', 'The RBI MPC maintained the Policy Repo Rate at 6.50% while reiterating its commitment to aligning CPI headline inflation to the 4% target on a durable basis.', 'The Committee underscored the efficacy of the Standing Deposit Facility (SDF) in absorbing excess system liquidity without pledging G-Secs. Key considerations included food price volatility and resilient domestic GDP growth.', 'Economy', 'Press Information Bureau (PIB) / Reserve Bank of India', 'https://rbi.org.in/pressreleases', 1, 'Verified against official RBI Monetary Policy Statement and Ministry of Finance economic records.', '["UPSC GS3 Economy","TNPSC Economy","Banking Financial Awareness","SSC General Awareness"]', '2026-08-20', '2026-08-27 09:11:41');
INSERT INTO `current_affairs` (`id`, `title`, `summary`, `detailed_analysis`, `category`, `source_name`, `source_url`, `is_verified`, `verification_notes`, `exam_relevance_tags`, `published_date`, `created_at`) VALUES ('ca_02_sc_verdict_subclassification', 'Supreme Court 7-Judge Constitution Bench Upholds Sub-Classification within Scheduled Castes', 'A 6:1 majority verdict affirmed that States possess constitutional competence under Articles 14, 15, and 16 to sub-classify Scheduled Castes for targeted affirmative action.', 'The Court held that sub-classification does not violate Article 341 so long as empirical data demonstrates inadequate representation of the sub-group without 100% exclusion of other groups.', 'Polity & Governance', 'Supreme Court of India Official Judgment Records', 'https://main.sci.gov.in/judgments', 1, 'Verified from landmark Constitution Bench judgment in State of Punjab v. Davinder Singh & Ors.', '["UPSC GS2 Polity","TNPSC Unit 9 Administration","State PSC Legal Studies"]', '2026-08-15', '2026-08-27 09:11:41');
INSERT INTO `current_affairs` (`id`, `title`, `summary`, `detailed_analysis`, `category`, `source_name`, `source_url`, `is_verified`, `verification_notes`, `exam_relevance_tags`, `published_date`, `created_at`) VALUES ('ca_03_tn_green_energy', 'Tamil Nadu Launches India’s First Port-Anchored Green Hydrogen Valley in Thoothukudi', 'Tamil Nadu notified policy incentives to develop 4 GW offshore wind infrastructure in the Gulf of Mannar and establish India’s first green hydrogen hub at VO Chidambaranar Port in Thoothukudi.', 'Aligns directly with Tamil Nadu’s roadmap to achieve a $1 Trillion economy and 50% renewable energy installed capacity by 2030, reinforcing Unit 9 development administration benchmarks.', 'Environment & Economy', 'Department of Energy, Govt of Tamil Nadu', 'https://tn.gov.in/pressrelease', 1, 'Official Government Order and Ministry notification from Tamil Nadu State Secretariat.', '["TNPSC Unit 9","UPSC GS3 Environment & Economy","SSC General Awareness"]', '2026-08-10', '2026-08-27 09:11:41');
INSERT INTO `current_affairs` (`id`, `title`, `summary`, `detailed_analysis`, `category`, `source_name`, `source_url`, `is_verified`, `verification_notes`, `exam_relevance_tags`, `published_date`, `created_at`) VALUES ('ca_04_isro_chandrayaan_payload', 'ISRO Announces Next-Gen Lunar Polar Exploration (LUPEX) Joint Mission Objectives', 'ISRO and JAXA finalized payload specifications for the LUPEX mission to explore water ice in permanently shadowed lunar polar craters.', 'Crucial for UPSC GS-3 Science & Tech and SSC General Awareness questions on planetary exploration and indigenous rover engineering.', 'Science & Technology', 'ISRO / Department of Space, Govt of India', 'https://isro.gov.in', 1, 'Verified from Department of Space official mission dossier.', '["UPSC GS3 Science & Tech","SSC General Awareness","RRB NTPC Science"]', '2026-08-05', '2026-08-27 09:11:41');

