DROP TABLE IF EXISTS `topic_notes`;
CREATE TABLE `topic_notes` (
  `id` VARCHAR(64) PRIMARY KEY,
  `topic_id` VARCHAR(64),
  `exam_id` VARCHAR(64),
  `title` VARCHAR(255),
  `concept` LONGTEXT,
  `formulas` TEXT,
  `examples` LONGTEXT,
  `shortcuts` TEXT,
  `common_mistakes` TEXT,
  `quick_revision` TEXT,
  `practice_questions` LONGTEXT,
  `source_authority` VARCHAR(255) DEFAULT 'Official Standard Textbook & Gazette Reference',
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Data for `topic_notes` (2 rows)
INSERT INTO `topic_notes` (`id`, `topic_id`, `exam_id`, `title`, `concept`, `formulas`, `examples`, `shortcuts`, `common_mistakes`, `quick_revision`, `practice_questions`, `source_authority`, `created_at`, `updated_at`) VALUES ('note_syl_cgl_quant_percent', 'syl_cgl_quant_percent', 'exam_ssc_cgl', 'Percentage — Complete Master Guide, Formulas & Short Tricks', '### 1. Fundamental Concept of Percentage\nPercentage means **"per every hundred"** (derived from Latin *per centum*). A fraction $\\frac{a}{b}$ converted into percentage is:\n$$\\text{Percentage} = \\left( \\frac{a}{b} \\times 100 \\right)\\%$$\n\n#### Standard Fraction-to-Percentage Equivalence Table (Must Memorize):\n* $\\frac{1}{2} = 50\\%$\n* $\\frac{1}{3} = 33\\frac{1}{3}\\% = 33.33\\%$\n* $\\frac{1}{4} = 25\\%$\n* $\\frac{1}{5} = 20\\%$\n* $\\frac{1}{6} = 16\\frac{2}{3}\\% = 16.66\\%$\n* $\\frac{1}{7} = 14\\frac{2}{7}\\% = 14.28\\%$\n* $\\frac{1}{8} = 12\\frac{1}{2}\\% = 12.5\\%$\n* $\\frac{1}{9} = 11\\frac{1}{9}\\% = 11.11\\%$\n* $\\frac{1}{11} = 9\\frac{1}{11}\\% = 9.09\\%$\n* $\\frac{1}{12} = 8\\frac{1}{3}\\% = 8.33\\%$\n* $\\frac{1}{16} = 6.25\\%$\n\n### 2. Multiplicative Factor (MF) Method\nInstead of calculating $X + \\frac{20}{100}X$, multiply directly by the **Multiplicative Factor**:\n* $20\\% \\text{ increase} \\implies \\text{Multiply by } 1.20 \\text{ (or } \\frac{6}{5} \\text{)}$\n* $15\\% \\text{ decrease} \\implies \\text{Multiply by } 0.85 \\text{ (or } \\frac{17}{20} \\text{)}$\n* $37.5\\% \\text{ increase} \\implies 1 + \\frac{3}{8} = \\frac{11}{8}$', '[{"name":"Successive Percentage Change","formula":"Net Change = (a + b + (a * b) / 100) %","notes":"Use + for increase, - for decrease"},{"name":"Price x Consumption = Expenditure","formula":"If Price increases by x%, Consumption must reduce by [x / (100 + x)] * 100% to keep Expenditure constant.","notes":"Classic SSC CGL question type"},{"name":"A is x% more than B","formula":"B is less than A by: [x / (100 + x)] * 100%","notes":"Inverse variation ratio"},{"name":"Population After n Years (Compounded)","formula":"P_n = P_0 * (1 + r/100)^n","notes":"Applicable for town population or depreciation"}]', '[{"question":"The price of sugar increases by 25%. By how much percent must a family reduce its consumption so that the total monthly expenditure remains unchanged?","step1":"Step 1: Identify the standard relationship -> Price x Consumption = Constant.","step2":"Step 2: Price increase x = 25%. Applying the reduction formula: [x / (100 + x)] * 100%.","step3":"Step 3: Required Reduction = [25 / (100 + 25)] * 100 = (25 / 125) * 100 = (1 / 5) * 100 = 20%.","answer":"20% reduction in consumption."},{"question":"A person spends 75% of his income. When his income increases by 20% and his expenditure increases by 10%, what is the percentage increase in his savings?","step1":"Step 1: Assume Initial Income = 100. Then Initial Expenditure = 75, Initial Savings = 25.","step2":"Step 2: New Income = 100 * 1.20 = 120. New Expenditure = 75 + (10% of 75) = 75 + 7.5 = 82.5.","step3":"Step 3: New Savings = 120 - 82.5 = 37.5. Increase in Savings = 37.5 - 25 = 12.5.","step4":"Step 4: Percentage increase in savings = (12.5 / 25) * 100 = 50%.","answer":"50% increase in savings."}]', '["⚡ Fraction Conversion Shortcut: Never multiply by 100 in rough sheets; replace 16.66% directly with 1/6.","⚡ 3 Successive Changes Shortcut: For a, b, c, compute net(a, b) first using a + b + ab/100, then combine result with c.","⚡ Percentage & Zero cancellation: 32% of 250 is identical to 250% of 32 = (5/2) * 32 = 80 in 2 seconds."]', '["⚠️ Mistake: Applying a - b - ab/100 for two discounts. Correct formula for two successive discounts is: D = (a + b - ab/100)%.","⚠️ Mistake: Calculating percentage on the wrong base (e.g. dividing by new value instead of original value).","⚠️ Mistake: Confusing \\"increased by 20%\\" (new = 120%) with \\"increased to 20%\\" (new = 20%)."]', '* Percentage represents parts per 100.\n* Multiplicative factor: $+x\\% \\implies (1 + x/100)$; $-x\\% \\implies (1 - x/100)$.\n* Successive change: $a + b + \\frac{ab}{100}$.\n* If $A$ is $x\\%$ more than $B$, $B$ is $\\frac{x}{100+x} \\times 100\\%$ less than $A$.\n* Always check the base value before dividing!', '[{"id":"pq_pct_1","question":"If the length of a rectangle is increased by 20% and its breadth is decreased by 10%, what is the net percentage change in its area?","options":["8% increase","10% increase","12% increase","2% decrease"],"correct_index":0,"explanation":"Net area change = a + b + (ab/100) = 20 - 10 + (20 * -10)/100 = 10 - 2 = +8% (8% increase)."},{"id":"pq_pct_2","question":"In an examination, 65% of students passed in Mathematics and 70% passed in English, while 15% failed in both. If 200 students passed in both subjects, what is the total number of students?","options":["300","400","500","600"],"correct_index":1,"explanation":"Total students passed in at least one subject = 100% - 15% = 85%. Using Set Theory: P(M U E) = P(M) + P(E) - P(M ∩ E) => 85% = 65% + 70% - Both => Both = 135% - 85% = 50%. Since 50% = 200, Total 100% = 400."}]', 'NCERT Mathematics Class 8-10 & SSC CGL TCS Question Bank 2018-2025', '2026-08-27 09:11:41', '2026-08-27 09:11:41');
INSERT INTO `topic_notes` (`id`, `topic_id`, `exam_id`, `title`, `concept`, `formulas`, `examples`, `shortcuts`, `common_mistakes`, `quick_revision`, `practice_questions`, `source_authority`, `created_at`, `updated_at`) VALUES ('note_syl_upsc_polity_fr', 'syl_upsc_polity_fr', 'exam_upsc_cse', 'Fundamental Rights (Part III, Articles 12–35) — Constitutional Doctrine & Landmark Precedents', '### 1. Constitutional Foundation of Fundamental Rights\nPart III of the Constitution of India (Articles 12 to 35) is rightfully described as the **Magna Carta of India**. They are justiciable and enforceable directly by the Supreme Court under Article 32 and High Courts under Article 226.\n\n#### The 6 Broad Categories of Fundamental Rights:\n1. **Right to Equality (Articles 14–18)**:\n   * Article 14: Equality before law & equal protection of the laws.\n   * Article 15: Prohibition of discrimination on grounds of religion, race, caste, sex, or place of birth.\n   * Article 16: Equality of opportunity in public employment.\n   * Article 17: Abolition of Untouchability.\n   * Article 18: Abolition of Titles.\n2. **Right to Freedom (Articles 19–22)**:\n   * Article 19: Protection of 6 fundamental freedoms (Speech, Assembly, Association, Movement, Residence, Profession).\n   * Article 20: Protection in respect of conviction for offenses (No ex-post facto law, No double jeopardy, No self-incrimination).\n   * Article 21: Protection of Life and Personal Liberty (Maneka Gandhi doctrine: "Procedure established by law" must be "fair, just and reasonable").\n   * Article 21A: Right to free & compulsory education (86th Amendment Act, 2002).\n   * Article 22: Protection against arrest and preventive detention.\n3. **Right against Exploitation (Articles 23–24)**:\n   * Article 23: Prohibition of traffic in human beings and forced labor (*begar*).\n   * Article 24: Prohibition of employment of children in factories/mines under 14 years.\n4. **Right to Freedom of Religion (Articles 25–28)**:\n   * Article 25: Freedom of conscience, profession, practice, and propagation.\n   * Article 26: Freedom to manage religious affairs.\n5. **Cultural and Educational Rights (Articles 29–30)**:\n   * Article 29: Protection of language, script, and culture of minorities.\n   * Article 30: Right of religious & linguistic minorities to establish and administer educational institutions.\n6. **Right to Constitutional Remedies (Article 32)**:\n   * Dr. B.R. Ambedkar termed Article 32 as the **"Heart and Soul of the Constitution"**.', '[{"name":"5 Prerogative Writs under Art 32 / 226","formula":"Habeas Corpus (\\"To have the body\\"), Mandamus (\\"We command\\"), Prohibition (\\"To forbid\\"), Certiorari (\\"To be certified\\"), Quo-Warranto (\\"By what authority\\")","notes":"Art 32 scope is limited to Part III; Art 226 scope is wider (covers legal rights)."},{"name":"Basic Structure Doctrine","formula":"Judicial Review (Art 13/32), Federalism, Rule of Law, Secularism cannot be abrogated even by Constitutional Amendment (Art 368).","notes":"Kesavananda Bharati v. State of Kerala (1973)"}]', '[{"question":"Can Parliament amend Fundamental Rights under Article 368? Explain with landmark Supreme Court precedents.","step1":"Phase 1 (Shankari Prasad 1951 & Sajjan Singh 1965): Supreme Court held Parliament can amend any part including Part III.","step2":"Phase 2 (Golak Nath 1967): Supreme Court ruled Fundamental Rights are transcendental and Parliament cannot curtail them.","step3":"Phase 3 (Kesavananda Bharati 1973): Supreme Court established Basic Structure Doctrine — Parliament has constituent power to amend any article including Fundamental Rights, provided the basic structure is not violated.","step4":"Phase 4 (Minerva Mills 1980): Re-affirmed harmonious balance between Part III (Fundamental Rights) and Part IV (DPSP).","answer":"Yes, Parliament can amend Fundamental Rights as long as the Basic Structure of the Constitution is not damaged."}]', '["⚡ Rights available ONLY to Indian Citizens (Not Foreigners): Articles 15, 16, 19, 29, and 30.","⚡ Rights that CANNOT be suspended during National Emergency (Art 352): Articles 20 and 21 (44th Amendment Act, 1978).","⚡ Golden Triangle of Indian Constitution: Articles 14, 19, and 21 must be read together (Maneka Gandhi case 1978)."]', '["⚠️ Mistake: Assuming Right to Property is still a Fundamental Right. It was deleted from Part III by 44th Amendment 1978 and is now a Legal Right under Article 300A.","⚠️ Mistake: Thinking Article 32 writ jurisdiction of Supreme Court is wider than High Court Article 226. High Court writ jurisdiction is wider because it covers both Fundamental Rights and general legal rights.","⚠️ Mistake: Confusing Article 19 freedoms with absolute rights. All Article 19 rights are subject to \\"Reasonable Restrictions\\" under Art 19(2)-19(6)."]', '* Part III (Articles 12-35) = Magna Carta of India.\n* Available only to Citizens: Articles 15, 16, 19, 29, 30.\n* Non-suspendable during Emergency: Articles 20 & 21.\n* Article 32: Constitutional Remedies (Habeas Corpus, Mandamus, Prohibition, Certiorari, Quo-Warranto).\n* Right to Education (Art 21A): Added by 86th Amendment Act, 2002.\n* Kesavananda Bharati (1973): Basic Structure Doctrine.', '[{"id":"pq_pol_1","question":"Which of the following Fundamental Rights is/are available to both Indian citizens and foreigners (except enemy aliens)?","options":["Article 15","Article 16","Article 19","Article 21"],"correct_index":3,"explanation":"Article 21 (Right to Life and Personal Liberty) is available to all persons, whether citizens or foreigners. Articles 15, 16, 19, 29, and 30 are available strictly to Indian citizens only."},{"id":"pq_pol_2","question":"A writ of Prohibition can be issued against which of the following bodies?","options":["Administrative authorities","Judicial and quasi-judicial bodies only","Legislative assemblies","Private individuals and corporations"],"correct_index":1,"explanation":"The writ of Prohibition can be issued only against judicial and quasi-judicial authorities to prevent them from exceeding their jurisdiction."}]', 'Constitution of India & M. Laxmikanth Indian Polity (7th Edition)', '2026-08-27 09:11:41', '2026-08-27 09:11:41');

DROP TABLE IF EXISTS `ca_rag_documents`;
CREATE TABLE `ca_rag_documents` (
  `id` VARCHAR(64) PRIMARY KEY,
  `title` VARCHAR(255),
  `summary` TEXT,
  `what_happened` TEXT,
  `why_important` TEXT,
  `key_facts` TEXT,
  `category` VARCHAR(100) DEFAULT 'National',
  `published_date` DATE,
  `source_name` TEXT,
  `source_url` VARCHAR(512),
  `retrieved_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  `last_updated` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  `embedding` TEXT,
  `relevance_score` DECIMAL(5,2) DEFAULT 9.5,
  `exam_relevance_tags` TEXT,
  `syllabus_topic_ids` TEXT,
  `mcqs` TEXT,
  `one_liners` TEXT,
  `is_verified` INT DEFAULT 1,
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Data for `ca_rag_documents` (5 rows)
INSERT INTO `ca_rag_documents` (`id`, `title`, `summary`, `what_happened`, `why_important`, `key_facts`, `category`, `published_date`, `source_name`, `source_url`, `retrieved_at`, `last_updated`, `embedding`, `relevance_score`, `exam_relevance_tags`, `syllabus_topic_ids`, `mcqs`, `one_liners`, `is_verified`, `created_at`) VALUES ('ca_rag_pib_semiconductor_2026', 'Cabinet Approves ₹76,000 Crore India Semiconductor Mission 2.0 with 3 New Fabrication Units', 'The Union Cabinet chaired by the Prime Minister approved the expansion of the India Semiconductor Mission (ISM 2.0), sanctioning three new commercial semiconductor fabrication and advanced packaging facilities in Gujarat and Assam.', 'The Union Cabinet approved a financial outlay under ISM 2.0 to establish India\'s first commercial 28nm silicon fab in Dholera, Gujarat, alongside high-density OSAT facilities in Sanand and Morigaon, Assam. The cumulative capital investment exceeds ₹1.26 lakh crore with 50% central fiscal support on pari-passu basis.', 'Critical for UPSC GS-3 (Science & Tech / Industrial Policy), SSC CGL General Awareness, and Banking PO Economy sections. It reduces electronic component import dependency from East Asia and bolsters indigenous chip design under the Design Linked Incentive (DLI) scheme.', '["Administering Body: India Semiconductor Mission (ISM) under Ministry of Electronics & IT (MeitY)","Primary Fabrication Hub: Dholera Special Investment Region (SIR), Gujarat (Tata Electronics in partnership with PSMC Taiwan)","Packaging (OSAT) Hubs: Morigaon (Assam) and Sanand (Gujarat)","Fiscal Subsidy: 50% capital subsidy on pari-passu basis by Government of India","Target Node Technologies: 28nm, 40nm, and 90nm trailing nodes for automotive, power, and telecom semiconductors"]', 'Science & Technology', '2026-08-20', 'Press Information Bureau (PIB Delhi)', 'https://pib.gov.in/PressReleasePage.aspx?PRID=semiconductor2026', '2026-08-26 08:30:00', '2026-08-27 09:11:41', NULL, 9.8, '["SSC CGL","UPSC CSE","Banking PO","RRB NTPC","State PSC"]', '["syl_upsc_econ_macro","syl_cgl_ga_polity"]', '[{"question":"Under the India Semiconductor Mission (ISM), what percentage of fiscal support is provided by the Central Government on a pari-passu basis for setting up semiconductor fabs?","options":["25%","33%","50%","75%"],"correct_answer":"C","explanation":"Under ISM guidelines, the Government of India provides 50% of the project cost on a pari-passu basis to eligible applicants establishing Silicon Semiconductor Fabs in India."},{"question":"India\'s first semiconductor packaging (OSAT) facility in North-East India has been sanctioned in which state?","options":["Tripura","Assam","Meghalaya","Sikkim"],"correct_answer":"B","explanation":"The commercial semiconductor OSAT facility was sanctioned at Morigaon in Assam with an investment of ₹27,000 crore."}]', '["India Semiconductor Mission 2.0 fiscal outlay: ₹76,000 Crore with 50% central support.","First Commercial Fab location: Dholera Special Investment Region (SIR), Gujarat.","North-East OSAT Facility: Morigaon, Assam."]', 1, '2026-08-27 09:11:41');
INSERT INTO `ca_rag_documents` (`id`, `title`, `summary`, `what_happened`, `why_important`, `key_facts`, `category`, `published_date`, `source_name`, `source_url`, `retrieved_at`, `last_updated`, `embedding`, `relevance_score`, `exam_relevance_tags`, `syllabus_topic_ids`, `mcqs`, `one_liners`, `is_verified`, `created_at`) VALUES ('ca_rag_rbi_monetary_policy_aug2026', 'RBI Monetary Policy Committee Keeps Repo Rate Unchanged at 6.50%; CPI Inflation Target at 4.5%', 'The Reserve Bank of India Monetary Policy Committee (MPC) unanimously decided to keep the policy repo rate unchanged at 6.50% while maintaining the policy stance focused on "withdrawal of accommodation" to ensure inflation aligns with the 4% target.', 'During the bi-monthly Monetary Policy meeting, RBI Governor announced that the Standing Deposit Facility (SDF) rate remains at 6.25% and the Marginal Standing Facility (MSF) rate at 6.75%. Real GDP growth for FY27 is projected at 7.2% with core inflation exhibiting broad-based softening.', 'Crucial for RBI Grade B Phase 1 & 2 (ESI), SBI PO General Awareness, SSC CGL Economy, and UPSC CSE GS-3. Direct questions are frequently asked on policy rates, MPC constitution under Section 45ZB of RBI Act 1934, and inflation targets.', '["Policy Repo Rate: 6.50%","Standing Deposit Facility (SDF) Rate: 6.25%","Marginal Standing Facility (MSF) Rate: 6.75%","Statutory Liquidity Ratio (SLR): 18.00%","Cash Reserve Ratio (CRR): 4.50%","MPC Legal Basis: Section 45ZB of the Reserve Bank of India Act, 1934 (6 Members: 3 RBI + 3 External)","Statutory Inflation Target: 4% (+/- 2% tolerance band, i.e., 2% to 6%)"]', 'Banking', '2026-08-18', 'Reserve Bank of India Official Bulletin', 'https://rbi.org.in/Scripts/BS_PressReleaseDisplay.aspx?prid=mpc_aug2026', '2026-08-26 09:15:00', '2026-08-27 09:11:41', NULL, 9.9, '["RBI Grade B","SBI PO","IBPS PO","SSC CGL","UPSC CSE"]', '["syl_bank_econ_rbi","syl_upsc_econ_macro"]', '[{"question":"Under Section 45ZB of the RBI Act 1934, how many total members constitute the Monetary Policy Committee (MPC)?","options":["4 Members","5 Members","6 Members","8 Members"],"correct_answer":"C","explanation":"The MPC consists of 6 members: the RBI Governor (Chairperson), the Deputy Governor in charge of monetary policy, one officer of the Bank, and three external experts appointed by the Central Government."},{"question":"What is the current lower and upper tolerance limit for Consumer Price Index (CPI) inflation targeting in India?","options":["1% and 5%","2% and 6%","3% and 7%","0% and 4%"],"correct_answer":"B","explanation":"Under the Flexible Inflation Targeting (FIT) framework, the target is 4% with a tolerance band of +/- 2%, meaning the lower limit is 2% and the upper limit is 6%."}]', '["Policy Repo Rate: 6.50% | SDF: 6.25% | MSF: 6.75% | CRR: 4.50%.","Statutory Inflation Target: 4% (+/- 2% tolerance band).","Monetary Policy Committee constitution: Section 45ZB of RBI Act, 1934."]', 1, '2026-08-27 09:11:41');
INSERT INTO `ca_rag_documents` (`id`, `title`, `summary`, `what_happened`, `why_important`, `key_facts`, `category`, `published_date`, `source_name`, `source_url`, `retrieved_at`, `last_updated`, `embedding`, `relevance_score`, `exam_relevance_tags`, `syllabus_topic_ids`, `mcqs`, `one_liners`, `is_verified`, `created_at`) VALUES ('ca_rag_isro_chandrayaan4_2026', 'ISRO Announces Architecture for Chandrayaan-4 Lunar Sample Return Mission and Bharatiya Antariksh Station', 'The Indian Space Research Organisation (ISRO) unveiled the official modular design for the Chandrayaan-4 mission aimed at returning lunar soil and rock samples from the Moon’s south pole, deploying a 5-module spacecraft configuration across two LVM3 rocket launches.', 'ISRO Chairman revealed that Chandrayaan-4 will consist of 5 modules: Propulsion Module, Lander Module, Ascender Module, Transfer Module, and Re-entry Module. It involves docking in lunar orbit and Earth orbit, testing technologies vital for the planned 2040 Indian Crewed Moon Landing and the 2035 Bharatiya Antariksh Station (BAS-1).', 'High-probability question in UPSC CSE GS-3 Science & Tech, SSC CGL General Awareness, GATE, and State PSC exams. Tests knowledge of launch vehicle capabilities, orbital mechanics, and national space roadmap milestones.', '["Agency: Indian Space Research Organisation (ISRO)","Mission Goal: Lunar South Pole Sample Return and automated docking in lunar orbit","Spacecraft Modules (5): Propulsion, Lander, Ascender, Transfer, Re-entry","Launch Architecture: Two separate launches of LVM3 rocket with space docking","National Space Milestones: Gaganyaan (Crewed LEO), BAS-1 (Space Station by 2035), Crewed Moon Landing (by 2040)"]', 'Science & Technology', '2026-08-15', 'ISRO Official Media Cell', 'https://isro.gov.in/chandrayaan4_mission_specs.html', '2026-08-26 10:00:00', '2026-08-27 09:11:41', NULL, 9.7, '["UPSC CSE","SSC CGL","ISRO SC","GATE","TNPSC Group 1"]', '["syl_upsc_env_climate","syl_cgl_ga_polity"]', '[{"question":"How many spacecraft modules comprise the Chandrayaan-4 Lunar Sample Return Mission architecture?","options":["3 Modules","4 Modules","5 Modules","6 Modules"],"correct_answer":"C","explanation":"Chandrayaan-4 utilizes a 5-module configuration: Propulsion Module, Lander Module, Ascender Module, Transfer Module, and Re-entry Module."},{"question":"By which target year has the Government of India mandated ISRO to establish the first module of the Bharatiya Antariksh Station (BAS)?","options":["2028","2030","2035","2040"],"correct_answer":"C","explanation":"The Union Cabinet roadmap targets operationalization of the Bharatiya Antariksh Station (BAS-1) by 2035 and an Indian crewed moon landing by 2040."}]', '["Chandrayaan-4: 5-Module configuration for Lunar South Pole Sample Return.","Bharatiya Antariksh Station (BAS) target year: 2035.","Indian Crewed Moon Landing target year: 2040."]', 1, '2026-08-27 09:11:41');
INSERT INTO `ca_rag_documents` (`id`, `title`, `summary`, `what_happened`, `why_important`, `key_facts`, `category`, `published_date`, `source_name`, `source_url`, `retrieved_at`, `last_updated`, `embedding`, `relevance_score`, `exam_relevance_tags`, `syllabus_topic_ids`, `mcqs`, `one_liners`, `is_verified`, `created_at`) VALUES ('ca_rag_defence_tarang_shakti_2026', 'Exercise Tarang Shakti 2026: Indian Air Force Conducts Largest Multilateral Air Exercise in SOG', 'The Indian Air Force (IAF) conducted "Exercise Tarang Shakti", the largest multilateral air combat exercise hosted on Indian soil with participation from 10 air forces including Germany, France, USA, UK, and Australia at Sulur and Jodhpur air bases.', 'Over 150 fighter aircraft including Rafale, Eurofighter Typhoon, F-18 Super Hornet, Tejas LCA, and Su-30MKI participated in complex Beyond Visual Range (BVR) combat scenarios, Large Force Engagements (LFE), and interoperability drills.', 'Direct relevance for NDA, CDS, AFCAT, SSC CGL, CAPF AC, and UPSC GS-3 (Security). Defense exercises, host locations, and participating partner nations are standard exam questions.', '["Host: Indian Air Force (IAF)","Exercise Name: Tarang Shakti 2026","Air Bases: Air Force Station Sulur (Tamil Nadu) and AFS Jodhpur (Rajasthan)","Key Participating Nations: India, USA, France, Germany, United Kingdom, Australia, Singapore, UAE, Japan","Key Indigenous Assets Showcased: LCA Tejas, Prachand Light Combat Helicopter, Netra AEW&C"]', 'Defence', '2026-08-12', 'Ministry of Defence Press Release', 'https://pib.gov.in/PressReleasePage.aspx?PRID=tarangshakti2026', '2026-08-26 10:45:00', '2026-08-27 09:11:41', NULL, 9.6, '["NDA","CDS","AFCAT","CAPF AC","SSC CGL","UPSC CSE"]', '["syl_upsc_polity_fr"]', '[{"question":"Where was Phase-1 of the Indian Air Force\'s largest multilateral air exercise \\"Tarang Shakti\\" held?","options":["AFS Ambala (Haryana)","AFS Sulur (Tamil Nadu)","AFS Hindon (Uttar Pradesh)","AFS Leh (Ladakh)"],"correct_answer":"B","explanation":"Phase-1 of Exercise Tarang Shakti was conducted at Air Force Station Sulur in Tamil Nadu, followed by Phase-2 at Jodhpur in Rajasthan."}]', '["Exercise Tarang Shakti: Largest multilateral air exercise hosted by Indian Air Force.","Locations: AFS Sulur (Tamil Nadu) and AFS Jodhpur (Rajasthan)."]', 1, '2026-08-27 09:11:41');
INSERT INTO `ca_rag_documents` (`id`, `title`, `summary`, `what_happened`, `why_important`, `key_facts`, `category`, `published_date`, `source_name`, `source_url`, `retrieved_at`, `last_updated`, `embedding`, `relevance_score`, `exam_relevance_tags`, `syllabus_topic_ids`, `mcqs`, `one_liners`, `is_verified`, `created_at`) VALUES ('ca_rag_tn_pudhumai_penn_2026', 'Tamil Nadu Expands Moovalur Ramamirtham Ammaiyar Higher Education Assurance Scheme (Pudhumai Penn)', 'The Government of Tamil Nadu announced the universal coverage expansion of the Pudhumai Penn and Tamil Pudhalvan Schemes, disbursing ₹1,000 monthly bank transfers directly to government and government-aided school students pursuing undergraduate degrees and polytechnic diplomas.', 'The Social Welfare and Women Empowerment Department released performance data showing a 34% increase in female gross enrollment ratio in higher education following the monthly Direct Benefit Transfer (DBT) of ₹1,000. The counterpart scheme for male students (Tamil Pudhalvan Scheme) was successfully extended to aided Tamil-medium school graduates.', 'High-frequency topic for TNPSC Group 1, Group 2/2A, Group 4 (Unit 9: Development Administration in Tamil Nadu), and UPSC GS-2 Social Justice/DBT governance.', '["State: Government of Tamil Nadu","Scheme Name: Pudhumai Penn Scheme (Moovalur Ramamirtham Ammaiyar Higher Education Assurance Scheme)","Male Counterpart: Tamil Pudhalvan Scheme","Financial Assistance: ₹1,000 per month direct bank transfer until completion of UG/Diploma/ITI","Eligibility: Students from Classes 6 to 12 in Government schools and aided Tamil-medium schools","Impact: 34% rise in female higher education enrollment across Tamil Nadu"]', 'State Current Affairs', '2026-08-10', 'Tamil Nadu Information and Public Relations Department (DIPR)', 'https://tn.gov.in/scheme/data_view/pudhumai_penn', '2026-08-26 11:30:00', '2026-08-27 09:11:41', NULL, 9.7, '["TNPSC Group 1","TNPSC Group 2","TNPSC Group 4","UPSC CSE","SSC CGL"]', '["syl_tnpsc_unit9_development"]', '[{"question":"Under the \\"Pudhumai Penn\\" scheme of Tamil Nadu, what is the monthly financial assistance provided to girl students pursuing higher education?","options":["₹500 / month","₹1,000 / month","₹1,500 / month","₹2,000 / month"],"correct_answer":"B","explanation":"Under the Moovalur Ramamirtham Ammaiyar Higher Education Assurance Scheme (Pudhumai Penn Scheme), ₹1,000 per month is deposited directly into the bank accounts of girl students until completion of their degree/diploma."}]', '["Pudhumai Penn Scheme assistance: ₹1,000 / month DBT for girl students from government schools.","Tamil Pudhalvan Scheme: ₹1,000 / month for male students pursuing higher education.","Administering Department: Social Welfare and Women Empowerment Department, Tamil Nadu."]', 1, '2026-08-27 09:11:41');

